16	const TRACER_NAME = 'gemini-cli';
17	const TRACER_VERSION = 'v1';
18	
19	/**
20	 * Metadata for a span.
21	 */
22	export interface SpanMetadata {
23	  /** The name of the span. */
24	  name: string;
25	  /** The input to the span. */
26	  input?: unknown;
27	  /** The output of the span. */
28	  output?: unknown;
29	  error?: unknown;
30	  /** Additional attributes for the span. */
31	  attributes: Record<string, AttributeValue>;
32	}
33	
34	/**
35	 * Runs a function in a new OpenTelemetry span.
36	 *
37	 * The `meta` object will be automatically used to set the span's status and attributes upon completion.
38	 *
39	 * @example
40	 * ```typescript
41	 * runInDevTraceSpan({ name: 'my-operation' }, ({ metadata }) => {
42	 *   metadata.input = { foo: 'bar' };
43	 *   // ... do work ...
44	 *   metadata.output = { result: 'baz' };
45	 *   metadata.attributes['my.custom.attribute'] = 'some-value';
46	 * });
47	 * ```
48	 *
49	 * @param opts The options for the span.
50	 * @param fn The function to run in the span.
51	 * @returns The result of the function.
52	 */
53	export async function runInDevTraceSpan<R>(
54	  opts: SpanOptions & { name: string; noAutoEnd?: boolean },
55	  fn: ({
56	    metadata,
57	  }: {
58	    metadata: SpanMetadata;
59	    endSpan: () => void;
60	  }) => Promise<R>,
61	): Promise<R> {
62	  const { name: spanName, noAutoEnd, ...restOfSpanOpts } = opts;
63	  if (process.env['GEMINI_DEV_TRACING'] !== 'true') {
64	    // If GEMINI_DEV_TRACING env var not set, we do not trace.
65	    return fn({
66	      metadata: {
67	        name: spanName,
68	        attributes: {},
69	      },
70	      endSpan: () => {
71	        // noop
72	      },
73	    });
74	  }
75	
76	  const tracer = trace.getTracer(TRACER_NAME, TRACER_VERSION);
77	  return tracer.startActiveSpan(opts.name, restOfSpanOpts, async (span) => {
78	    const meta: SpanMetadata = {
79	      name: spanName,
80	      attributes: {},
81	    };
82	    const endSpan = () => {
83	      try {
84	        if (meta.input !== undefined) {
85	          span.setAttribute('input-json', safeJsonStringify(meta.input));
86	        }
87	        if (meta.output !== undefined) {
88	          span.setAttribute('output-json', safeJsonStringify(meta.output));
89	        }
90	        for (const [key, value] of Object.entries(meta.attributes)) {
91	          span.setAttribute(key, value);
92	        }
93	        if (meta.error) {
94	          span.setStatus({
95	            code: SpanStatusCode.ERROR,
96	            message: getErrorMessage(meta.error),
97	          });
98	          if (meta.error instanceof Error) {
99	            span.recordException(meta.error);
100	          }
101	        } else {
102	          span.setStatus({ code: SpanStatusCode.OK });
103	        }
104	      } catch (e) {
105	        // Log the error but don't rethrow, to ensure span.end() is called.
106	        diag.error('Error setting span attributes in endSpan', e);
107	        span.setStatus({
108	          code: SpanStatusCode.ERROR,
109	          message: `Error in endSpan: ${getErrorMessage(e)}`,
110	        });
111	      } finally {
112	        span.end();
113	      }
114	    };
115	    try {
116	      return await fn({ metadata: meta, endSpan });
117	    } catch (e) {
118	      meta.error = e;
119	      if (noAutoEnd) {
120	        // For streaming operations, the delegated endSpan call will not be reached
121	        // on an exception, so we must end the span here to prevent a leak.
122	        endSpan();
123	      }
124	      throw e;
125	    } finally {
126	      if (!noAutoEnd) {
127	        // For non-streaming operations, this ensures the span is always closed,
128	        // and if an error occurred, it will be recorded correctly by endSpan.
129	        endSpan();
130	      }
131	    }
132	  });
133	}
134	
135	/**
136	 * Gets the error message from an error object.
137	 *
138	 * @param e The error object.
139	 * @returns The error message.
140	 */
141	function getErrorMessage(e: unknown): string {
142	  if (e instanceof Error) {
143	    return e.message;
144	  }
145	  if (typeof e === 'string') {
146	    return e;
147	  }
148	  return safeJsonStringify(e);
149	}
