429	        spanMetadata.input = request;
430	        if (this.isRunning() || this.isScheduling) {
431	          return new Promise((resolve, reject) => {
432	            const abortHandler = () => {
433	              // Find and remove the request from the queue
434	              const index = this.requestQueue.findIndex(
435	                (item) => item.request === request,
436	              );
437	              if (index > -1) {
438	                this.requestQueue.splice(index, 1);
439	                reject(new Error('Tool call cancelled while in queue.'));
440	              }
441	            };
442	
443	            signal.addEventListener('abort', abortHandler, { once: true });
444	
445	            this.requestQueue.push({
446	              request,
447	              signal,
448	              resolve: () => {
449	                signal.removeEventListener('abort', abortHandler);
450	                resolve();
451	              },
452	              reject: (reason?: Error) => {
453	                signal.removeEventListener('abort', abortHandler);
454	                reject(reason);
455	              },
456	            });
457	          });
458	        }
